-- Apply only after both production nodes run the reviewed reset-card release.
-- One transaction; refuses a changed catalog or settings. No wallet/rate writes.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
LOCK TABLE settings, subscription_plans IN SHARE ROW EXCLUSIVE MODE;
DO $guard$
BEGIN
 IF (SELECT count(*) FROM subscription_plans) <> 0 THEN RAISE EXCEPTION 'Catalog changed: expected no plans'; END IF;
 IF (SELECT COALESCE(jsonb_object_agg(key,value),'{}'::jsonb) FROM settings WHERE key IN ('MIN_RECHARGE_AMOUNT','MAX_RECHARGE_AMOUNT','BALANCE_RECHARGE_MULTIPLIER','SUBSCRIPTION_USD_TO_CNY_RATE','RECHARGE_FEE_RATE','PAYMENT_RECHARGE_OPTIONS','PAYMENT_BANNER','payment_visible_method_alipay_source','payment_visible_method_wxpay_source','payment_visible_method_alipay_enabled','payment_visible_method_wxpay_enabled','ENABLED_PAYMENT_TYPES','payment_enabled')) <> '{"payment_visible_method_wxpay_enabled": "false", "ENABLED_PAYMENT_TYPES": "", "RECHARGE_FEE_RATE": "0.00", "payment_enabled": "false", "MIN_RECHARGE_AMOUNT": "1.00", "BALANCE_RECHARGE_MULTIPLIER": "1.00", "MAX_RECHARGE_AMOUNT": "", "SUBSCRIPTION_USD_TO_CNY_RATE": "", "PAYMENT_RECHARGE_OPTIONS": "[]", "payment_visible_method_wxpay_source": "", "payment_visible_method_alipay_enabled": "false", "payment_visible_method_alipay_source": ""}'::jsonb THEN RAISE EXCEPTION 'Payment settings changed: re-audit before apply'; END IF;
 IF (SELECT count(*) FROM groups WHERE id IN (4,12) AND status='active' AND subscription_type='subscription' AND deleted_at IS NULL) <> 2 THEN RAISE EXCEPTION 'Subscription groups unavailable'; END IF;
 IF to_regclass('public.subscription_reset_card_purchases') IS NULL THEN RAISE EXCEPTION 'Reset purchase migration missing'; END IF;
END $guard$;
