ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value,updated_at=EXCLUDED.updated_at;
SELECT id,group_id,name,price,original_price,currency,validity_days,validity_unit,for_sale FROM subscription_plans ORDER BY sort_order,id;
COMMIT;
